public long roadsAndLibraries(int n, int cLib, int cRoad, int[][] roads) {
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());
    for (int[] r : roads) {
        adj.get(r[0]).add(r[1]);
        adj.get(r[1]).add(r[0]);
    }
    boolean[] visited = new boolean[n + 1];
    long total = 0;
    for (int start = 1; start <= n; start++) {
        if (visited[start]) continue;
        int size = 0;
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(start);
        visited[start] = true;
        while (!stack.isEmpty()) {          // iterative DFS, no stack overflow
            int u = stack.pop();
            size++;
            for (int v : adj.get(u)) {
                if (!visited[v]) {
                    visited[v] = true;
                    stack.push(v);
                }
            }
        }
        total += Math.min((long) size * cLib,
                          (long) cLib + (long) (size - 1) * cRoad);
    }
    return total;
}

