def roads_and_libraries(self, n: int, c_lib: int, c_road: int, roads: list[list[int]]) -> int:
    adj: list[list[int]] = [[] for _ in range(n + 1)]
    for u, v in roads:
        adj[u].append(v)
        adj[v].append(u)
    visited = [False] * (n + 1)
    total = 0
    for start in range(1, n + 1):
        if visited[start]:
            continue
        size = 0
        stack = [start]                      # iterative DFS, no recursion limit
        visited[start] = True
        while stack:
            u = stack.pop()
            size += 1
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    stack.append(v)
        total += min(size * c_lib, c_lib + (size - 1) * c_road)
    return total

