public long roadsAndLibraries(int n, int cLib, int cRoad, int[][] roads) {
    if (cLib <= cRoad) {
        return (long) n * cLib;          // libraries never lose — skip roads entirely
    }
    int[] parent = new int[n + 1];
    int[] rank = new int[n + 1];
    int[] size = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        parent[i] = i;
        size[i] = 1;
    }
    for (int[] r : roads) {
        union(parent, rank, size, r[0], r[1]);
    }
    long total = 0;
    for (int i = 1; i <= n; i++) {
        if (find(parent, i) == i) {       // i is a root → one component
            int s = size[i];
            total += (long) cLib + (long) (s - 1) * cRoad;
        }
    }
    return total;
}

private int find(int[] parent, int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];   // path halving, iterative
        x = parent[x];
    }
    return x;
}

private void union(int[] parent, int[] rank, int[] size, int a, int b) {
    int ra = find(parent, a), rb = find(parent, b);
    if (ra == rb) return;
    if (rank[ra] < rank[rb]) { int t = ra; ra = rb; rb = t; }
    parent[rb] = ra;
    size[ra] += size[rb];
    if (rank[ra] == rank[rb]) rank[ra]++;
}

code.python:
def roads_and_libraries(self, n: int, c_lib: int, c_road: int, roads: list[list[int]]) -> int:
    if c_lib <= c_road:
        return n * c_lib                 # libraries never lose
    parent = list(range(n + 1))
    rank = [0] * (n + 1)
    size = [1] * (n + 1)

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]   # path halving, iterative
            x = parent[x]
        return x

    def union(a: int, b: int) -> None:
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]
        if rank[ra] == rank[rb]:
            rank[ra] += 1

    for u, v in roads:
        union(u, v)

    total = 0
    for i in range(1, n + 1):
        if find(i) == i:                 # i is a root → one component
            s = size[i]
            total += c_lib + (s - 1) * c_road
    return total

